<template><AppLayout page-title="Mon panier"><div class="grid-2"><section class="card"><h3>Articles</h3><div v-if="!cart.items.length" class="empty-state">Votre panier est vide.<br><RouterLink to="/marketplace" class="btn btn-primary">Voir les médicaments</RouterLink></div><div v-for="i in cart.items" :key="i.id" class="list-row"><div><b>{{i.products?.name||i.product_id}}</b><div>{{Number(i.unit_price).toLocaleString('fr-FR')}} XOF</div></div><input class="input qty" type="number" min="1" :value="i.quantity" @change="cart.updateQuantity(i.id,Number(($event.target as HTMLInputElement).value))"><button class="btn btn-ghost" @click="cart.removeItem(i.id)">Supprimer</button></div></section><section class="card"><h3>Livraison</h3><select class="input" v-model="deliveryMode"><option value="pickup">Retrait en pharmacie</option><option value="standard_delivery">Livraison standard</option><option value="express_delivery">Livraison express</option></select><input class="input" v-model="address" placeholder="Adresse de livraison" style="margin-top:12px"><input class="input" v-model="city" placeholder="Ville" style="margin-top:12px"><textarea class="input" v-model="notes" placeholder="Note" rows="3" style="margin-top:12px"></textarea><div class="total">Total : <b>{{cart.totalAmount.toLocaleString('fr-FR')}} XOF</b></div><button class="btn btn-primary btn-lg" :disabled="!cart.items.length||checkout" @click="placeOrder">{{checkout?'Commande…':'Passer la commande'}}</button><p v-if="message">{{message}}</p></section></div></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {RouterLink,useRouter} from 'vue-router';import AppLayout from '@/components/layout/AppLayout.vue';import {useCartStore} from '@/stores/cart';const cart=useCartStore(),router=useRouter(),deliveryMode=ref('pickup'),address=ref(''),city=ref(''),notes=ref(''),checkout=ref(false),message=ref('');onMounted(()=>cart.fetchCart());async function placeOrder(){checkout.value=true;message.value='';try{const r=await cart.checkout(deliveryMode.value,address.value||undefined,city.value||undefined,undefined,notes.value||undefined);const id=(r as any)?.orderId||(r as any)?.order_id;router.push(id?`/orders/${id}`:'/orders')}catch(e:any){message.value=e.message||'Erreur'}finally{checkout.value=false}}</script>
